type HandlerFunc = bot.Handler

type Middleware func(next HandlerFunc) HandlerFunc

type Chain struct {
	middlewares []Middleware
}

func New(mws ...Middleware) *Chain {
	return &Chain{middlewares: mws}
}

func (c *Chain) Use(mws ...Middleware) *Chain {
	c.middlewares = append(c.middlewares, mws...)
	return c
}

func (c *Chain) Then(h HandlerFunc) HandlerFunc {
	for i := len(c.middlewares) - 1; i >= 0; i-- {
		h = c.middlewares[i](h)
	}
	return h
}

func Recover(log *slog.Logger) Middleware {
	if log == nil {
		log = slog.Default()
	}
	return func(next HandlerFunc) HandlerFunc {
		return func(ctx context.Context, s *discordgo.Session, i *discordgo.InteractionCreate, env *bot.Env) error {
			defer func() {
				if rec := recover(); rec != nil {
					log.Error("panic en handler",
						"panic", rec,
						"stack", string(debug.Stack()),
					)
				}
			}()
			return next(ctx, s, i, env)
		}
	}
}

func Logger(log *slog.Logger) Middleware {
	if log == nil {
		log = slog.Default()
	}
	return func(next HandlerFunc) HandlerFunc {
		return func(ctx context.Context, s *discordgo.Session, i *discordgo.InteractionCreate, env *bot.Env) error {
			start := time.Now()
			err := next(ctx, s, i, env)
			dur := time.Since(start)

			userID := ""
			if i.Member != nil && i.Member.User != nil {
				userID = i.Member.User.ID
			} else if i.User != nil {
				userID = i.User.ID
			}

			log.Info("interacci?n procesada",
				"type", i.Type,
				"guild", i.GuildID,
				"user", userID,
				"duration_ms", dur.Milliseconds(),
				"error", err,
			)
			return err
		}
	}
}

type CooldownStore struct {
	mu      sync.Mutex
	entries map[string]time.Time
}

func NewCooldownStore() *CooldownStore {
	return &CooldownStore{entries: make(map[string]time.Time)}
}

func (c *CooldownStore) Check(key string) time.Duration {
	c.mu.Lock()
	defer c.mu.Unlock()
	until, ok := c.entries[key]
	if !ok {
		return 0
	}
	remaining := time.Until(until)
	if remaining <= 0 {
		delete(c.entries, key)
		return 0
	}
	return remaining
}

func (c *CooldownStore) Set(key string, d time.Duration) {
	c.mu.Lock()
	c.entries[key] = time.Now().Add(d)
	c.mu.Unlock()
}

func (c *CooldownStore) GarbageCollect() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	now := time.Now()
	removed := 0
	for k, until := range c.entries {
		if now.After(until) {
			delete(c.entries, k)
			removed++
		}
	}
	return removed
}

